import{requireSession,error,json,supa,tenant}from'../_lib/core.js';
function visibleTask(t,s){if(['admin','owner'].includes(s.role))return t;const{dropbox_path,...rest}=t,meta={...(rest.metadata||{})};delete meta.dropbox_link;delete meta.dropbox_path;delete meta.xero_invoice_id;delete meta.invoice_total;return{...rest,metadata:meta}}
function filterTasks(rows,s){const alive=rows.filter(x=>!x.deleted_at);if(['admin','owner'].includes(s.role))return alive.map(x=>visibleTask(x,s));const current=alive.filter(x=>!x.archived_at);if(s.role==='agent')return current.filter(x=>x.agent_user_id===s.userId).map(x=>visibleTask(x,s));if(s.role==='photographer')return current.filter(x=>x.photographer_user_id===s.userId).map(x=>visibleTask(x,s));if(s.role==='editor')return current.filter(x=>x.editor_user_id===s.userId).map(x=>visibleTask(x,s));return[]}
function userView(u,s){if(['admin','owner'].includes(s.role))return u;return{id:u.id,role_code:u.role_code,name:u.name,active:u.active}}
function providersFor(rows,s){if(['admin','owner','agent'].includes(s.role))return rows.map(p=>{const{live_location,...rest}=p;return rest});if(s.role==='photographer')return rows.filter(p=>p.user_id===s.userId).map(p=>{const{live_location,...rest}=p;return rest});return[]}
export async function onRequestGet({request,env}){const a=await requireSession(request,env);if(a.error)return a.error;try{const[t,users,services,packages,providers,roles,tasks,integrations]=await Promise.all([tenant(env),supa(env,'users',{query:'select=id,tenant_id,role_code,name,email,phone,active,avatar_url,metadata&active=eq.true&order=name.asc'}),supa(env,'services',{query:'select=*&active=eq.true&order=sort_order.asc'}),supa(env,'packages',{query:'select=*&active=eq.true&order=name.asc'}),supa(env,'provider_profiles',{query:'select=*'}),supa(env,'roles',{query:'select=id,code,name,permissions&order=name.asc'}),supa(env,'tasks',{query:'select=*&deleted_at=is.null&order=created_at.desc'}),supa(env,'integration_state',{query:'select=provider,status,account_label,last_verified_at&order=provider.asc'})]);return json({session:a.session,tenant:{id:t.id,slug:t.slug,name:t.name,brand_name:t.brand_name,timezone:t.timezone,settings:['admin','owner'].includes(a.session.role)?t.settings:{}},users:users.map(u=>userView(u,a.session)),services,packages,providers:providersFor(providers,a.session),roles:['admin','owner'].includes(a.session.role)?roles:[],tasks:filterTasks(tasks,a.session),integrations:['admin','owner'].includes(a.session.role)?integrations:[]})}catch(e){return error(500,'Could not load Northlight workspace.',e.message)}}
